    private void btnConfirmActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnConfirmActionPerformed
        String senha = new String(txtSenha.getPassword());
        int idade = (int) spIdade.getValue();
        String turno = "";
        String nome = txtNome.getText();
        
        if (rbManha.isSelected()){
            turno = "Manha";
            
        }else if (rbTarde.isSelected()){
            turno = "Tarde";
        }else {
            turno = "Noite";
        }
        
        String cursos = "";
        
        if(cbJava.isSelected()){
            cursos += "Java\n";
        }if (cbJavaScript.isSelected()){
            cursos += "Javascrpit\n";
        }if (cbTypeScript.isSelected()){
            cursos += "TypeScript\n";
        }
        
        JOptionPane.showMessageDialog(this,"Seu nome : "+nome+"\nSua senha : "+ senha+"\nTurno :"+turno+"\n Seus cursos : \n"+cursos);
    }//GEN-LAST:event_btnConfirmActionPerformed

